def are_all_rows_has_consecutive_seats(seats):
    for row in seats:
        found_pair = False
        # If row length < 2, can't have 2 consecutive seats
        if len(row) < 2:
            return False
        for i in range(len(row) - 1):
            # Check the pair at i, i+1
            if row[i] == 0 and row[i+1] == 0:
                found_pair = True
                break
        if not found_pair:
            return False
    return True
